(function(){ 'use strict'; var d=document, b=d.body; function qs(s,c){return (c||d).querySelector(s)} function qsa(s,c){return Array.prototype.slice.call((c||d).querySelectorAll(s))} function on(el,ev,fn,opt){if(el){el.addEventListener(ev,fn,opt||false)}} function closest(el,sel){return el && (el.closest ? el.closest(sel) : null)} function setExpanded(btn,state){ if(btn){btn.setAttribute('aria-expanded',state?'true':'false');btn.classList.toggle('active',!!state);} } function closeSidebar(){ var sb=qs('.dashboard-shell .sidebar'); var ov=qs('.mq-sidebar-overlay'); if(sb){sb.classList.remove('is-open');} if(ov){ov.classList.remove('is-open');} b.classList.remove('fq95-no-scroll'); } function openSidebar(){ var sb=qs('.dashboard-shell .sidebar'); var ov=qs('.mq-sidebar-overlay'); if(sb){sb.classList.add('is-open');} if(ov){ov.classList.add('is-open');} b.classList.add('fq95-no-scroll'); } function enhanceTables(){ qsa('.page-body table, .menuqr-cart-wrap table, .menuqr-checkout-wrap table').forEach(function(t){ if(closest(t,'.table-responsive,.data-table-wrap')) return; var wrap=d.createElement('div'); wrap.className='table-responsive fq95-table-wrap'; t.parentNode.insertBefore(wrap,t); wrap.appendChild(t); }); } function enhanceExternalImages(){ qsa('img:not([loading])').forEach(function(img){ if(!closest(img,'.nav-logo,.sidebar-logo,.menuqr-topbar-brand')) img.setAttribute('loading','lazy'); img.setAttribute('decoding','async'); }); } function showTinyMessage(msg){ var old=qs('#fq95-toast'); if(old) old.remove(); var el=d.createElement('div'); el.id='fq95-toast'; el.textContent=msg; el.style.cssText='position:fixed;left:50%;bottom:86px;transform:translateX(-50%);z-index:10050;background:#05050f;color:#fff;padding:11px 14px;border-radius:999px;box-shadow:0 16px 45px rgba(0,0,0,.35);font:800 13px system-ui;max-width:calc(100vw - 28px);text-align:center'; d.body.appendChild(el); setTimeout(function(){el.remove();},2600); } function initAjaxLoading(){ if(!window.jQuery) return; var $=window.jQuery; $(d).ajaxStart(function(){ b.classList.add('fq95-ajax-busy'); }); $(d).ajaxStop(function(){ b.classList.remove('fq95-ajax-busy'); }); $(d).on('click','[data-kitchen-order][data-status], #menuqr-place-order, #menuqr-create-qr, #menuqr-save-template, #menuqr-bulk-generate, .add-btn, [data-add-item]',function(){ var el=this; el.classList.add('fq95-loading'); setTimeout(function(){el.classList.remove('fq95-loading');},900); }); } function init(){ enhanceTables(); enhanceExternalImages(); initAjaxLoading(); on(qs('.mq-sidebar-toggle'),'click',function(e){ e.preventDefault(); var sb=qs('.dashboard-shell .sidebar'); if(sb && sb.classList.contains('is-open')) closeSidebar(); else openSidebar(); }); on(qs('.mq-sidebar-overlay'),'click',closeSidebar); qsa('.dashboard-shell .sidebar a').forEach(function(a){on(a,'click',function(){ if(window.matchMedia('(max-width:1100px)').matches) closeSidebar(); });}); on(d,'keydown',function(e){ if(e.key==='Escape'){ closePublicMenu(); closeSidebar(); }}); var mo=new MutationObserver(function(){ enhanceTables(); enhanceExternalImages(); }); mo.observe(d.documentElement,{childList:true,subtree:true}); } if(d.readyState==='loading') on(d,'DOMContentLoaded',init); else init(); })();